import{_ as i,o as s,c as t,ai as o}from"./chunks/framework.lvpqbiZd.js";const m=JSON.parse('{"title":"Asumi Site Bootstrap Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/plans/2026-08-31-asumi-site-bootstrap.md","filePath":"superpowers/plans/2026-08-31-asumi-site-bootstrap.md"}'),a={name:"superpowers/plans/2026-08-31-asumi-site-bootstrap.md"};function r(n,e,p,c,l,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="asumi-site-bootstrap-implementation-plan" tabindex="-1">Asumi Site Bootstrap Implementation Plan <a class="header-anchor" href="#asumi-site-bootstrap-implementation-plan" aria-label="Permalink to “Asumi Site Bootstrap Implementation Plan”">​</a></h1><blockquote><p><strong>For agentic workers:</strong> REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (<code>- [ ]</code>) syntax for tracking.</p></blockquote><p><strong>Goal:</strong> Create a separate Frappe site at <code>asumi.ir</code>, install Press on it, and make it reachable securely without changing existing sites.</p><p><strong>Architecture:</strong> <code>asumi.ir</code> is a new Frappe site in the existing Docker bench. It uses the existing MariaDB, Redis, backend, scheduler, and websocket services. Frappe host-based routing maps the incoming hostname to the <code>sites/asumi.ir</code> directory; the existing web proxy must preserve the Host header.</p><p><strong>Tech Stack:</strong> Frappe v16, Press app, Docker Compose, MariaDB, Redis, host reverse proxy and TLS.</p><h2 id="global-constraints" tabindex="-1">Global Constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to “Global Constraints”">​</a></h2><ul><li>Create a new site only; never modify or delete <code>dehati.ir</code>, <code>denroom.ir</code>, or <code>veederakht.ir</code>.</li><li>Install only <code>frappe</code> and <code>press</code> for this bootstrap.</li><li>Do not print or commit the Administrator password.</li><li>Keep <code>erpyar.ir</code> unchanged until <code>asumi.ir</code> is verified over HTTPS.</li><li>Stop if <code>asumi.ir</code> already exists or Press installation fails.</li></ul><hr><h3 id="task-1-create-the-frappe-site" tabindex="-1">Task 1: Create the Frappe site <a class="header-anchor" href="#task-1-create-the-frappe-site" aria-label="Permalink to “Task 1: Create the Frappe site”">​</a></h3><p><strong>Files:</strong></p><ul><li>Create: <code>/home/sepehr/den-v16-docker/runtime/sites/asumi.ir/site_config.json</code> through <code>bench new-site</code>.</li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Consumes: DNS records for <code>asumi.ir</code> and shared bench configuration at <code>sites/common_site_config.json</code>.</p></li><li><p>Produces: an isolated Frappe site named <code>asumi.ir</code>.</p></li><li><p>[ ] Verify that <code>sites/asumi.ir</code> is absent and <code>asumi.ir</code> resolves to <code>62.60.207.82</code>.</p></li><li><p>[ ] Run <code>bench new-site asumi.ir</code> with database and Administrator passwords supplied only through command environment variables.</p></li><li><p>[ ] Verify <code>curl -H &#39;Host: asumi.ir&#39; http://127.0.0.1:8090/api/method/frappe.ping</code> returns <code>pong</code>.</p></li></ul><h3 id="task-2-install-press" tabindex="-1">Task 2: Install Press <a class="header-anchor" href="#task-2-install-press" aria-label="Permalink to “Task 2: Install Press”">​</a></h3><p><strong>Files:</strong></p><ul><li>Modify: <code>/home/sepehr/den-v16-docker/runtime/sites/asumi.ir/installed_apps.json</code> through Frappe installation.</li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Consumes: the new <code>asumi.ir</code> site and <code>/home/frappe/frappe-bench/apps/press</code>.</p></li><li><p>Produces: an Asumi site with Frappe and Press installed.</p></li><li><p>[ ] Confirm <code>python -c &#39;import press&#39;</code> succeeds inside the bench.</p></li><li><p>[ ] Run <code>bench --site asumi.ir install-app press</code>, <code>migrate --skip-search-index</code>, and <code>clear-cache</code>.</p></li><li><p>[ ] Verify <code>bench --site asumi.ir list-apps</code> includes <code>frappe</code> and <code>press</code>; verify <code>/desk</code> is non-5xx locally.</p></li></ul><h3 id="task-3-public-delivery-verification" tabindex="-1">Task 3: Public delivery verification <a class="header-anchor" href="#task-3-public-delivery-verification" aria-label="Permalink to “Task 3: Public delivery verification”">​</a></h3><p><strong>Files:</strong></p><ul><li>Verify: host proxy and TLS configuration, which are not committed to this repository.</li></ul><p><strong>Interfaces:</strong></p><ul><li><p>Consumes: the new Frappe site and the existing listeners on ports 80 and 443.</p></li><li><p>Produces: reachable HTTPS entrypoints for <code>asumi.ir</code> and <code>www.asumi.ir</code>.</p></li><li><p>[ ] Test HTTP and HTTPS for both Asumi hostnames.</p></li><li><p>[ ] If the proxy has no route or valid certificate, stop before changing <code>erpyar.ir</code> and report the exact missing configuration.</p></li><li><p>[ ] Commit only this plan document; never commit runtime site files, database credentials, or Administrator credentials.</p></li></ul>',23)])])}const u=i(a,[["render",r]]);export{m as __pageData,u as default};
